const b = $input.first().json;
const inbox = b.inbox || {};
const logseq = b.logseq || {};
const dec = b.decisions || {};

const totalUntagged = Object.values(inbox).reduce((s, v) => s + (v.untagged || 0), 0);
const totalFiles = Object.values(inbox).reduce((s, v) => s + (v.total || 0), 0);

const lines = [
  `=== SECOND BRAIN BRIEF: ${new Date().toISOString().slice(0,10)} ===`,
  ``,
  `Inbox     : ${totalFiles} files  (${totalUntagged} untagged)`,
  `  claude-sessions : ${inbox['claude-sessions']?.total || 0}`,
  `  transcripts     : ${inbox['transcripts']?.total || 0}`,
  `  gmail           : ${inbox['gmail']?.total || 0}`,
  ``,
  `Logseq    : ${logseq.pages || 0} pages  |  ${logseq.journals || 0} journals`,
  ``,
  `Decisions : ${dec.total || 0} total  |  ${dec.approved || 0} approved`,
  `Last file : ${dec.last_file || 'none'}`,
  `Last seen : ${dec.last_ts ? dec.last_ts.slice(0,16) : 'never'}`,
];

return [{ json: { summary: lines.join('\n'), raw: b } }];
